import hashlib
import math

class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array to probabilistically
    test whether an element is a member of a set. This implementation calculates
    the optimal size of the bit array and the number of hash functions to minimize
    the probability of false positives based on the expected number of items and 
    the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.size = self._optimal_size(expected_items, false_positive_rate)
        self.num_hashes = self._optimal_num_hashes(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _optimal_size(self, n: int, p: float) -> int:
        """Calculates the optimal size of the bit array."""
        return math.ceil(- (n * math.log(p)) / (math.log(2) ** 2))

    def _optimal_num_hashes(self, m: int, n: int) -> int:
        """Calculates the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generates multiple hash values for the item."""
        hash_values = []
        for i in range(self.num_hashes):
            hash_input = f"{item}:{i}".encode()
            hash_value = int(hashlib.md5(hash_input).hexdigest(), 16) % self.size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Adds an item to the Bloom filter."""
        for h in self._hashes(item):
            self.bit_array[h] = 1

    def contains(self, item: str) -> bool:
        """Checks if the item is in the Bloom filter."""
        return all(self.bit_array[h] for h in self._hashes(item))

