import hashlib
import math

class BloomFilter:
    """
    A BloomFilter class implementing a probabilistic data structure for 
    membership testing. The Bloom filter uses a bit array and hash functions 
    to efficiently determine if an item is possibly in a set or definitely not in it.

    The optimal bit array size and number of hash functions are calculated 
    based on the expected number of items and the desired false positive rate.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._calculate_bit_array_size()
        self.hash_count = self._calculate_number_of_hashes()
        self.bit_array = [0] * self.size

    def _calculate_bit_array_size(self) -> int:
        """Calculate the optimal bit array size using the formula."""
        return math.ceil(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_number_of_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Create multiple hash values for the given item."""
        hash_results = []
        for i in range(self.hash_count):
            hash_result = hashlib.md5(f"{item}:{i}".encode()).hexdigest()  # Using md5 for hashing
            hash_index = int(hash_result, 16) % self.size
            hash_results.append(hash_index)
        return hash_results

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
